{
  "review_date": "2026-11-03",
  "memory_gate": {
    "qvac_revision": "69a8cd98c",
    "source": "packages/diffusion-cpp/addon/src/model-interface/SdModel.cpp:580",
    "finding": "assessFit returns unknown for an explicit backend or explicit per-module placement. vae_conv_direct is forwarded by fillCtxParams, but the fit workload has no temporal-tiling request field.",
    "consequence": "Do not implement an automatic higher-memory API-specific profile by treating an unknown estimate as a successful fit. Keep explicit opt-in or validate a backend-aware capacity gate; preserve the existing fallback and explicit overrides."
  },
  "additional_research": [
    {
      "idea": "Metal IM2COL_3D parallel packing",
      "source": "https://github.com/0xShug0/audio.cpp/pull/1169",
      "source_revision": "0c6bb4dcc3e77f0f9bb9816d86155e6c62123886",
      "status": "Pinned baseline and candidate pass all 22 CTests and the additional Metal validation layer operator run. First H3 short clip is byte-exact; paired inference and LTX screening ongoing.",
      "scope": "Four Metal backend files. Existing QVAC operation support is retained; change dispatch and packing layout without changing convolution arithmetic or checkpoints.",
      "model_scope": "H3 VAE decoder consists mainly of attention/feed-forward blocks; its post-quantization 3D convolution is small. First paired fresh-process clip shows unchanged VAE decode (57.13 versus 57.15 seconds). LTX convolution-heavy decoder is the more relevant performance target.",
      "test_scope": "16 shape/output-type cases, F16 and F32 packing, changing inputs, offset strided views, batches, stride/dilation/padding, bounded-grid loop, independent existing Metal gather/cast and direct-convolution references. Test adapted to pinned F16 convolution-weight contract, with negative F32-weight/F16-packing admission coverage. Every existing test remains enabled.",
      "remaining_operator_coverage": "The greater-than-2^32 output-element 64-bit-index specialization is not executed by the current test sizes. Do not describe it as covered."
    },
    {
      "idea": "Strix quantized matrix multiplication versus hipBLAS selection",
      "source": "https://github.com/ggml-org/llama.cpp/blob/master/docs/build.md",
      "status": "Paired builds and native FLUX screening queued.",
      "scope": "GGML_CUDA_FORCE_MMQ or GGML_CUDA_FORCE_CUBLAS within the task-local HIP build. These are experimental compile choices, not production defaults. A useful result would require architecture/model/shape-scoped enablement and quality validation."
    },
    {
      "idea": "rocWMMA flash attention on Strix",
      "source": "https://github.com/ggml-org/llama.cpp/issues/24437",
      "status": "Not measured in this campaign; current HIP baseline already leaves this optional path off.",
      "scope": "A reported LLM prefill regression makes a blanket enablement poorly justified. The report is not diffusion evidence and cannot by itself prove a diffusion regression."
    },
    {
      "idea": "Alternative runtimes on new platforms",
      "sources": [
        "https://github.com/vllm-project/vllm-metal/blob/main/docs/supported_models.md",
        "https://github.com/sgl-project/sglang/blob/main/python/sglang/multimodal_gen/README.md",
        "https://github.com/vllm-project/vllm-omni/blob/main/recipes/MiniMaxAI/MiniMax-H3.md"
      ],
      "finding": "Published vLLM Metal support lists language/vision-language models, not these image/video generators. SGLang Diffusion ROCm guidance targets AMD Instinct; vLLM H3 ROCm validation names gfx942/gfx950 BF16, not gfx1151 and our GGUF checkpoints.",
      "consequence": "Retain dated Spark measurements. Do not infer that an Instinct recipe validates Strix or that vLLM Metal text-model support enables diffusion. No new matched-runtime measurements are claimed."
    },
    {
      "idea": "Token-axis H3 MLP chunking for Vulkan buffer limits",
      "source": "https://github.com/leejet/stable-diffusion.cpp/pull/2257",
      "related_issue": "https://github.com/leejet/stable-diffusion.cpp/issues/2242",
      "finding": "Merged 1 November. One model header change chunks large feed-forward activations using backend maximum buffer size and retains single-pass processing below the limit. The reported 4 GiB limit is crossed above 37,449 tokens; it is a per-buffer limit rather than total VRAM exhaustion.",
      "status": "Source review only. Current 960x544x124 and short screening cases are below the reported threshold. Do not claim speedup on these cases; a larger-frame conditional experiment needs separate memory and output validation."
    },
    {
      "idea": "Avoid blanket upstream memory-manager upgrade",
      "source": "https://github.com/leejet/stable-diffusion.cpp/issues/1976",
      "finding": "Upstream reported video-specific segmentation and residency regressions in an older 16 GiB Vulkan configuration. This is a different device and revision, not evidence of failure in our measured baseline.",
      "consequence": "Prefer isolated kernels and paired tests against the pinned QVAC engine; validate repeated generation and memory before recommending any residency or scheduler changes."
    },
    {
      "idea": "Backend-specific convolution selection versus upstream auto probes",
      "sources": [
        "https://github.com/leejet/stable-diffusion.cpp/blob/master/docs/backend.md",
        "https://github.com/leejet/stable-diffusion.cpp/blob/master/docs/performance.md",
        "https://github.com/leejet/stable-diffusion.cpp/issues/1215"
      ],
      "finding": "Current upstream documents per-module convolution selection and small Vulkan probes, while warning that the selected kernel need not minimize full-generation latency. The earlier Klein issue independently reports poor ROCm VAE direct-convolution performance.",
      "consequence": "Use our same-checkpoint end-to-end results to scope profiles. Do not copy an upstream automatic policy or broaden a CUDA/HIP result to Vulkan/Metal without validation. Upstream auto-probe code is not part of the pinned QVAC engine experiment."
    },
    {
      "idea": "Metal flash-attention vector tuning tables",
      "source": "https://github.com/ggml-org/llama.cpp/discussions/27668",
      "finding": "The published tuner targets the vector attention path and a full sweep takes hours. In the pinned Metal implementation, ggml_metal_op_flash_attn_ext_use_vec selects that path only when the query dimension is below 20 and the head size is divisible by 32.",
      "consequence": "Source-reviewed only. Large diffusion self-attention tensors are a different workload; published LLM decode gains are not evidence for a diffusion gain. Prioritize measured decoder and H3 graph changes within this booking."
    },
    {
      "idea": "Krea Vulkan fork optimizations on Strix",
      "source": "https://github.com/leejet/stable-diffusion.cpp/pull/1891",
      "finding": "The proposed engine/GGML combination reports a gain on Krea2 Turbo and explicitly describes non-identical images. It is a different model and a broader engine/backend fork.",
      "consequence": "Do not import the whole fork or claim its Krea speedup for H3, FLUX or LTX. Any reusable kernel needs a focused pinned-engine backport and our own quality/performance evidence."
    },
    {
      "idea": "Metal IM2COL_3D dispatch grouping without arithmetic changes",
      "finding": "The pinned kernel launches one thread per threadgroup. A one-file experiment instead groups up to 128 existing per-output-position threads, preserving the kernel, layouts, numeric operations and existing large-position fallback.",
      "status": "Operator tests and repeated LTX screens queued. Distinct from the four-file per-packed-element rewrite, whose first apparent total gain was confounded by checkpoint reads and whose video-decode stage was slower."
    },
    {
      "idea": "FLUX Q8 matrix expansion to F16 at load time",
      "finding": "Existing tensor_type_rules can expand only the diffusion transformer block weight matrices into F16 while keeping the text encoder, decoder, model file and sampling schedule unchanged. This may trade memory for repeated matrix multiplication speed on integrated GPUs.",
      "status": "Native screens queued on M3 Ultra Metal and Strix Vulkan/HIP. Validate that the rule actually matches tensors, measure memory/startup as well as warm latency, and compare output before recommending. This is not the original unquantized checkpoint and it must not be described as one."
    }
  ]
}

