'use strict'
const fs = require('bare-fs')
const path = require('bare-path')
const process = require('bare-process')
const os = require('bare-os')
const root = __dirname
const spec = JSON.parse(fs.readFileSync(path.resolve(process.argv[2]), 'utf8'))
const output = path.join(root, 'results', spec.name)
fs.mkdirSync(output, { recursive: true })
const Model = spec.kind === 'video' ? require('@qvac/diffusion-cpp/video') : require('@qvac/diffusion-cpp')
const logging = require(path.join(root, 'node_modules/@qvac/diffusion-cpp/addonLogging.js'))
const addonVersion = JSON.parse(fs.readFileSync(path.join(root, 'node_modules/@qvac/diffusion-cpp/package.json'), 'utf8')).version
const report = { name: spec.name, platform: os.platform(), arch: os.arch(), addonVersion, spec, runs: [], resolvedBackends: [], nativeEvents: [] }
const save = () => {
  const temporary = path.join(output, 'metrics.tmp')
  fs.writeFileSync(temporary, JSON.stringify(report, null, 2))
  fs.renameSync(temporary, path.join(output, 'metrics.json'))
}
logging.setLogger((priority, message) => {
  const text = String(message).trim()
  if (/runtime backend:|params backend|Backend selection:|GGML backend device|using device|compute buffer size|peak.*memory/i.test(text)) report.resolvedBackends.push(text)
  if (/EasyCache|CacheDIT|UCache|Spectrum|flash.attention|conv.*direct|im2col/i.test(text)) report.nativeEvents.push(text)
  console.log('NATIVE', priority, text)
})
async function main () {
  const files = Object.fromEntries(Object.entries(spec.files).map(([key, file]) => [key, path.resolve(root, file)]))
  const config = { verbosity: 2, threads: 8, ...spec.config }
  if (config.backendsDir) config.backendsDir = path.resolve(root, config.backendsDir)
  const model = new Model({ files, config, opts: { stats: true }, logger: console })
  try {
    const started = Date.now()
    await model.load()
    report.loadWallMs = Date.now() - started
    save()
    for (let promptIndex = 0; promptIndex < spec.requests.length; promptIndex++) {
      const request = spec.requests[promptIndex]
      for (let index = 0; index < spec.warmupRuns + spec.runs; index++) {
        const started = Date.now()
        const response = await model.run(request.params)
        const run = { promptIndex, index, warmup: index < spec.warmupRuns, name: request.name, firstProgressMs: null, firstOutputMs: null, outputBytes: 0, outputFiles: [], stats: null }
        response.on('stats', value => { run.stats = value })
        await response.onUpdate(value => {
          if (value instanceof Uint8Array) {
            if (run.firstOutputMs === null) run.firstOutputMs = Date.now() - started
            const filename = `${promptIndex}-${index}-${run.outputFiles.length}.${spec.kind === 'video' ? 'avi' : 'png'}`
            fs.writeFileSync(path.join(output, filename), value)
            run.outputFiles.push(filename)
            run.outputBytes += value.length
          } else {
            if (run.firstProgressMs === null) run.firstProgressMs = Date.now() - started
            console.log('PROGRESS', request.name, index, Date.now() - started, String(value))
          }
        }).await()
        if (!run.outputFiles.length) throw new Error('No generated output')
        run.wallMs = Date.now() - started
        run.stats = run.stats || response.stats
        report.runs.push(run)
        save()
        console.log('BENCH_RUN', JSON.stringify(run))
      }
    }
  } finally {
    await model.unload()
    logging.releaseLogger()
  }
  report.completed = true
  save()
  console.log('BENCH_COMPLETE', spec.name)
}
main().catch(error => { report.error = String(error.stack || error); save(); console.error(error); process.exitCode = 1 })

